def _round(value: float) -> float:
    return round(value, 1)


def _expand(rect: Rect, margin: float) -> Rect:
    return Rect(rect.min_x - margin, rect.min_y - margin, rect.max_x + margin, rect.max_y + margin)


def _overlaps(a: Rect, b: Rect) -> bool:
    return a.min_x <= b.max_x and b.min_x <= a.max_x and a.min_y <= b.max_y and b.min_y <= a.max_y


def _clear(x: float, y: float, rects: tuple[Rect, ...] | list[Rect], margin: float) -> bool:
    return not any(_expand(rect, margin).contains(x, y) for rect in rects)


def _prep_island() -> Rect:
    return Rect(_PREP_OFFSET, _PREP_OFFSET, _PREP_OFFSET + _PREP_SIZE, _PREP_OFFSET + _PREP_SIZE)


def _place_pois(spec: _MapSpec, rng: random.Random, grid: int) -> list[PointOfInterest]:
    """Spread POIs over the map, away from edges, water, the prep island and each other."""
    radius = grid * _BUILDING_CELL / 2 + 15.0
    margin = 150.0
    min_spacing = spec.size / (len(spec.poi_names) ** 0.5) * 0.6
    prep_guard = _expand(_prep_island(), 200.0)
    pois: list[PointOfInterest] = []
    for name in spec.poi_names:
        for _ in range(2000):
            x = rng.uniform(margin, spec.size - margin)
            y = rng.uniform(margin, spec.size - margin)
            if prep_guard.contains(x, y) or not _clear(x, y, spec.water, radius + 30.0):
                continue
            if any(math.hypot(x - o.x, y - o.y) < min_spacing for o in pois):
                continue
            weight = _round(rng.uniform(0.8, 1.5))
            pois.append(PointOfInterest(name, _round(x), _round(y), radius, weight))
            break
        else:  # pragma: no cover - spacing is generous enough for every shipped spec
            raise RuntimeError(f"Could not place POI {name!r} on {spec.map_id!r}")
    return pois


def _town_buildings(poi: PointOfInterest, rng: random.Random, grid: int) -> list[Rect]:
    """Buildings on a grid around the POI. The centre cell stays open as a plaza."""
    half = grid * _BUILDING_CELL / 2
    buildings: list[Rect] = []
    for row in range(grid):
        for col in range(grid):
            if row == grid // 2 and col == grid // 2:
                continue
            if rng.random() < 0.3:
                continue
            cx = poi.x - half + (col + 0.5) * _BUILDING_CELL + rng.uniform(-2.0, 2.0)
            cy = poi.y - half + (row + 0.5) * _BUILDING_CELL + rng.uniform(-2.0, 2.0)
            w = rng.uniform(8.0, 14.0)
            h = rng.uniform(8.0, 14.0)
            buildings.append(Rect(_round(cx - w / 2), _round(cy - h / 2), _round(cx + w / 2), _round(cy + h / 2)))
    return buildings


def _rocks(spec: _MapSpec, rng: random.Random, pois: list[PointOfInterest], taken: list[Rect]) -> list[Rect]:
    prep_guard = _expand(_prep_island(), 30.0)
    rocks: list[Rect] = []
    while len(rocks) < spec.rock_count:
        x = rng.uniform(40.0, spec.size - 40.0)
        y = rng.uniform(40.0, spec.size - 40.0)
        w = rng.uniform(2.0, 5.0)
        h = rng.uniform(2.0, 5.0)
        rock = Rect(_round(x - w / 2), _round(y - h / 2), _round(x + w / 2), _round(y + h / 2))
        if prep_guard.contains(x, y) or any(math.hypot(x - p.x, y - p.y) < p.radius + 10 for p in pois):
            continue
        if any(_overlaps(_expand(rock, 6.0), other) for other in (*spec.water, *taken, *rocks)):
            continue
        rocks.append(rock)
    return rocks


def _loot_spawns(
    pois: list[PointOfInterest], rng: random.Random, blockers: list[Rect], water: tuple[Rect, ...]
) -> list[tuple[float, float]]:
    spawns: list[tuple[float, float]] = []
    for poi in pois:
        wanted = int(55 * poi.loot_weight)
        placed = 0
        while placed < wanted:
            angle = rng.uniform(0.0, math.tau)
            dist = poi.radius * math.sqrt(rng.random())
            x = _round(poi.x + math.cos(angle) * dist)
            y = _round(poi.y + math.sin(angle) * dist)
            if not _clear(x, y, blockers, _LOOT_MARGIN) or inside_any(x, y, water):
                continue
            spawns.append((x, y))
            placed += 1
    return spawns


def _door_points(buildings: list[Rect], blockers: list[Rect], water: tuple[Rect, ...]) -> list[tuple[float, float]]:
    """One door per building, just outside the middle of its south (else north) wall."""
    doors: list[tuple[float, float]] = []
    for b in buildings:
        cx = _round((b.min_x + b.max_x) / 2)
        for y in (_round(b.min_y - 0.5), _round(b.max_y + 0.5)):
            if not inside_any(cx, y, blockers) and not inside_any(cx, y, water):
                doors.append((cx, y))
                break
    return doors


def _vehicle_spawns(
    spec: _MapSpec, rng: random.Random, pois: list[PointOfInterest], blockers: list[Rect]
) -> list[tuple[float, float]]:
    prep_guard = _expand(_prep_island(), 20.0)
    spawns: list[tuple[float, float]] = []
    while len(spawns) < spec.vehicle_count:
        poi = pois[len(spawns) % len(pois)]
        angle = rng.uniform(0.0, math.tau)
        dist = rng.uniform(poi.radius + 10.0, poi.radius + 80.0)
        x, y = clamp_to_map(poi.x + math.cos(angle) * dist, poi.y + math.sin(angle) * dist, spec.size - 20.0)
        x, y = _round(max(x, 20.0)), _round(max(y, 20.0))
        if prep_guard.contains(x, y):
            continue
        if not _clear(x, y, blockers, _VEHICLE_CLEARANCE) or not _clear(x, y, spec.water, _VEHICLE_CLEARANCE):
            continue
        spawns.append((x, y))
    return spawns


def build_map(map_id: str) -> MapDefinition:
    """Generate a development layout from its fixed seed. Raises KeyError for an unknown id."""
    if map_id == MAP700_DEV_ID:
        return build_map700_dev()
    spec = _SPECS[map_id]
    rng = random.Random(spec.seed)
    grid = 4
    pois = _place_pois(spec, rng, grid)
    buildings: list[Rect] = []
    for poi in pois:
        buildings.extend(_town_buildings(poi, rng, grid))
    rocks = _rocks(spec, rng, pois, buildings)
    blockers = buildings + rocks
    loot = _loot_spawns(pois, rng, blockers, spec.water)
    doors = _door_points(buildings, blockers, spec.water)
    vehicles = _vehicle_spawns(spec, rng, pois, blockers)
    return MapDefinition(
        map_id=spec.map_id,
        display_name=spec.display_name,
        size=spec.size,
        prep_island=_prep_island(),
        blockers=tuple(blockers),
        water=spec.water,
        pois=tuple(pois),
        loot_spawns=tuple(loot),
        vehicle_spawns=tuple(vehicles),
        door_points=tuple(doors),
        initial_zone_radius=spec.size * 0.75,
    )


