# map700_dev: development stand-in for client map 700 (gateway Phases A and B)

MAP700_DEV_ID = "map700_dev"
# Client map 700 CIRCLE_BOUND_BOX (min X, min Z, max X, max Z) in client units, as recorded in
# docs/SOLO_GATEWAY_ADAPTER.md section 5.1. Only its extent is used here.
MAP700_CLIENT_BOUND_BOX = (-22429.98, -20648.09, 8450.52, 10375.44)
# PLACEHOLDER scale: engine metres = client units / 100. The real client-unit-to-metre scale is
# UNKNOWN (blocker B3). The gateway transform file owns the real mapping; nothing here is used to
# convert coordinates.
MAP700_DEV_UNITS_PER_METRE = 100.0
_MAP700_DEV_LOOT_PER_POI = 16


def _map700_dev_size() -> float:
    min_x, min_z, max_x, max_z = MAP700_CLIENT_BOUND_BOX
    extent = max(max_x - min_x, max_z - min_z) / MAP700_DEV_UNITS_PER_METRE
    return math.ceil(extent * 10.0) / 10.0  # square, covering both axes, rounded up to 0.1 m


def build_map700_dev() -> MapDefinition:
    """DEVELOPMENT PLACEHOLDER for client map 700. Not original geometry.

    A square engine map whose side covers the extent of the client's CIRCLE_BOUND_BOX for map
    700 (the larger of its X and Z widths), expressed as client units / 100. That scale is a
    placeholder: the real scale, axes and origin are unknown (B3), and the gateway's map 700
    transform data file owns the real mapping. No blockers, no water and no vehicles, because no
    map 700 collision, water or vehicle data exists yet. The preparation island, POIs and loot
    spawns are invented development values so bots have somewhere to go; none of them is an
    original map 700 position.
    """
    size = _map700_dev_size()
    prep = Rect(10.0, 10.0, 40.0, 40.0)
    names = ("Dev North", "Dev East", "Dev Centre", "Dev West")
    fractions = ((0.30, 0.72), (0.72, 0.68), (0.50, 0.45), (0.25, 0.35))
    radius = _round(size * 0.08)
    pois = tuple(
        PointOfInterest(name, _round(size * fx), _round(size * fy), radius, 1.0)
        for name, (fx, fy) in zip(names, fractions, strict=True)
    )
    loot: list[tuple[float, float]] = []
    for poi in pois:
        for k in range(_MAP700_DEV_LOOT_PER_POI):
            angle = math.tau * k / _MAP700_DEV_LOOT_PER_POI
            dist = radius * (0.3 + 0.6 * (k % 2))
            loot.append((_round(poi.x + math.cos(angle) * dist), _round(poi.y + math.sin(angle) * dist)))
    return MapDefinition(
        map_id=MAP700_DEV_ID,
        display_name="Map 700 (development placeholder)",
        size=size,
        prep_island=prep,
        blockers=(),
        water=(),
        pois=pois,
        loot_spawns=tuple(loot),
        vehicle_spawns=(),
        door_points=(),
        initial_zone_radius=size * 0.75,
    )


SYNTHETIC_MAPS: tuple[str, ...] = tuple(_SPECS)  # generated ghillie / fearless layouts
MAPS: dict[str, MapDefinition] = {map_id: build_map(map_id) for map_id in _SPECS}
MAPS[MAP700_DEV_ID] = build_map700_dev()
KNOWN_MAPS: tuple[str, ...] = tuple(MAPS)


def get_map(map_id: str) -> MapDefinition:
    """Return the layout for `map_id`. Raises KeyError for an unknown id."""
    if map_id not in MAPS:
        raise KeyError(f"Unknown map {map_id!r}")
    return MAPS[map_id]


def is_open_point(game_map: MapDefinition, x: float, y: float) -> bool:
    """Inside the map, not in a blocker, not in water. Blockers go through the cached index."""
    if not (0.0 <= x <= game_map.size and 0.0 <= y <= game_map.size):
        return False
    return not blocker_index(game_map).contains(x, y) and not inside_any(x, y, game_map.water)


def random_open_point(
    game_map: MapDefinition, rng: random.Random, within: Rect | None = None
) -> tuple[float, float]:
    """A random point inside the map (and `within`, when given) that is not a blocker or water.

    Falls back to the whole map, then to the preparation island centre, which is always open.
    """
    areas: list[Rect] = []
    if within is not None:
        clipped = Rect(
            max(within.min_x, 0.0), max(within.min_y, 0.0),
            min(within.max_x, game_map.size), min(within.max_y, game_map.size),
        )
        if clipped.min_x <= clipped.max_x and clipped.min_y <= clipped.max_y:
            areas.append(clipped)
    areas.append(Rect(0.0, 0.0, game_map.size, game_map.size))
    for area in areas:
        for _ in range(200):
            x = rng.uniform(area.min_x, area.max_x)
            y = rng.uniform(area.min_y, area.max_y)
            if is_open_point(game_map, x, y):
                return x, y
    prep = game_map.prep_island
    return (prep.min_x + prep.max_x) / 2, (prep.min_y + prep.max_y) / 2


def is_valid_landing(game_map: MapDefinition, x: float, y: float) -> bool:
    """Inside the map and not in a blocker. Water is a valid landing: the participant swims."""
    if not all(math.isfinite(v) for v in (x, y)):
        return False
    if not (0.0 <= x <= game_map.size and 0.0 <= y <= game_map.size):
        return False
    return not blocker_index(game_map).contains(x, y)
